SELECT complaint_time AS complaintTime, dept_name AS deptName, person_name AS personName, position, category, result, remark FROM TR_SVC_QUALITY_CMPL c INNER JOIN TR_DEPT_DICT d ON c.dept_code = d.dept_code WHERE c.stat_date BETWEEN #{startDate} AND #{endDate}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
ORDER BY c.complaint_time DESC

SELECT praise_time AS praiseTime, dept_name AS deptName, person_name AS personName, position, method, feedback, remark FROM TR_SVC_QUALITY_PRZ p INNER JOIN TR_DEPT_DICT d ON p.dept_code = d.dept_code WHERE p.stat_date BETWEEN #{startDate} AND #{endDate}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
ORDER BY p.praise_time DESC
